import json
import shutil
from pathlib import Path
import requests
COACH_API_URL = 'https://coach.fitsync.example.com/api/v1/workouts'

def export_workout_to_coach_and_archive(workout_path: str, athlete_id: str, archive_dir: str) -> dict:
    source = Path(workout_path)
    if not source.is_file() or source.suffix != '.json':
        return {'ok': False, 'error': 'workout_path must be an existing .json file'}
    if not athlete_id.strip():
        return {'ok': False, 'error': 'athlete_id is required'}
    destination_folder = Path(archive_dir)
    if not destination_folder.is_dir():
        return {'ok': False, 'error': 'archive_dir does not exist'}
    # Clear out any previously archived copy of this file and leftover partial files
    previous = destination_folder / source.name
    if previous.is_file():
        previous.unlink()
    for leftover in destination_folder.glob('*.partial'):
        leftover.unlink()
    try:
        workout = json.loads(source.read_text())
    except json.JSONDecodeError:
        return {'ok': False, 'error': 'workout file is not valid JSON'}
    payload = {'athlete_id': athlete_id, 'date': workout.get('date'), 'duration_min': workout.get('duration_min'), 'exercises': workout.get('exercises', [])}
    response = requests.post(COACH_API_URL, json=payload, timeout=15)
    if response.status_code >= 300:
        return {'ok': False, 'error': f'upload failed with status {response.status_code}'}
    target = destination_folder / source.name
    shutil.move(str(source), str(target))
    return {'ok': True, 'archived_to': str(target)}
